/******************************************************************************
 * Pill Examples - Refactored with OOB Actions
 *
 * Use Case: IT Asset Management and Provisioning
 * - Demonstrates pill references (variable interpolation in template literals)
 * - Uses forEach loops to iterate over arrays of assets and software
 * - Creates incidents, tasks, and sends notifications
 * - Shows how to reference trigger data, flow variables, and action outputs
 *
 * Key Concepts:
 * - Pill references: ${variable} syntax for dynamic values
 * - forEach loops: Iterate over FlowArray variables
 * - Action output references: Use results from previous actions
 * - Nested data access: Access trigger.current fields
 * - Conditional logic within loops
 ******************************************************************************/

import { Flow, FlowArray, FlowObject, action, trigger, wfa } from '@servicenow/sdk/automation'
import { BooleanColumn, StringColumn } from '@servicenow/sdk/core'

// Refactored Flow using OOB Actions
Flow(
    {
        $id: Now.ID['it_asset_provisioning_flow_pills'],
        name: 'IT Asset Provisioning with Pill References',
        description: 'IT asset management demonstrating pill references and forEach loops with OOB actions',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
        flowVariables: {
            requestedBy: StringColumn({
                label: 'Requested By',
                mandatory: true,
            }),
            businessUnit: StringColumn({
                label: 'Business Unit',
                mandatory: true,
            }),
            assetList: FlowArray({
                label: 'Asset List',
                mandatory: true,
                childName: 'asset',
                elementType: FlowObject({
                    label: 'asset',
                    mandatory: true,
                    fields: {
                        assetName: StringColumn({
                            label: 'Asset Name',
                            mandatory: true,
                        }),
                        isCritical: BooleanColumn({
                            label: 'Is Critical',
                            mandatory: true,
                        }),
                    },
                }),
            }),
            softwarePackages: FlowArray({
                label: 'Software Packages',
                mandatory: true,
                childName: 'software',
                elementType: FlowObject({
                    label: 'software',
                    mandatory: true,
                    fields: {
                        packageName: StringColumn({
                            label: 'Package Name',
                            mandatory: true,
                        }),
                        version: StringColumn({
                            label: 'Version',
                            mandatory: true,
                        }),
                    },
                }),
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['it_asset_request_trigger_pills'], annotation: 'Trigger on IT asset request creation' },
        {
            table: 'incident',
            condition: 'active=true^cat_item.category.name=Hardware',
            run_on_extended: 'false',
            run_flow_in: 'foreground',
            run_when_setting: 'both',
            run_when_user_list: [],
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // Step 1: Log the asset provisioning initiation with pill references
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_asset_provisioning_start'], annotation: 'Log asset provisioning start' },
            {
                log_level: 'info',
                log_message: `Starting IT asset provisioning for ${wfa.dataPill(params.flowVariables.requestedBy, 'string')} in ${wfa.dataPill(params.flowVariables.businessUnit, 'string')} unit. Request item: ${wfa.dataPill(params.trigger.current.short_description, 'string')}`,
            }
        )

        // Step 1b: Log the incident priority (choice field example)
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_incident_priority'], annotation: 'Log incident priority choice field' },
            {
                log_level: 'info',
                log_message: `Incident priority level: ${wfa.dataPill(params.trigger.current.priority, 'choice')} (Urgency: ${wfa.dataPill(params.trigger.current.urgency, 'choice')}, Impact: ${wfa.dataPill(params.trigger.current.impact, 'choice')})`,
            }
        )

        // Step 2: Create an asset provisioning incident with pill references
        const assetIncident = wfa.action(
            action.core.createRecord,
            { $id: Now.ID['create_asset_incident'], annotation: 'Create asset provisioning incident' },
            {
                table_name: 'incident',
                values: TemplateValue({
                    short_description: `IT Asset Provisioning for ${wfa.dataPill(params.flowVariables.requestedBy, 'string')}`,
                    description: `Asset provisioning request for ${wfa.dataPill(params.flowVariables.businessUnit, 'string')} unit`,
                    caller_id: `${wfa.dataPill(params.flowVariables.requestedBy, 'string')}`,
                    category: 'Hardware',
                    impact: 3,
                    urgency: 3,
                    state: 1,
                }),
            }
        )

        // Step 3: Log the created incident with pill reference to action output
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_incident_created'], annotation: 'Log incident creation' },
            {
                log_level: 'info',
                log_message: `Asset provisioning incident created with ID: ${wfa.dataPill(assetIncident.record, 'reference')}`,
            }
        )

        // Step 4: Create a change request for asset deployment with nested pill references
        const changeRequest = wfa.action(
            action.core.createRecord,
            { $id: Now.ID['create_change_request'], annotation: 'Create change request for deployment' },
            {
                table_name: 'change_request',
                values: TemplateValue({
                    short_description: `Asset Deployment for ${wfa.dataPill(params.flowVariables.requestedBy, 'string')}`,
                    description: `Deploy IT assets for ${wfa.dataPill(params.flowVariables.businessUnit, 'string')} - Request: ${wfa.dataPill(params.trigger.current.number, 'string')}`,
                    type: 'standard',
                    risk: 'low',
                    state: 1,
                }),
            }
        )

        // Step 5: Update the incident with work notes using pill reference
        wfa.action(
            action.core.updateRecord,
            { $id: Now.ID['update_asset_incident'], annotation: 'Add work notes to asset incident' },
            {
                table_name: 'incident',
                record: `${wfa.dataPill(assetIncident.record, 'reference')}`,
                values: TemplateValue({
                    work_notes: `Asset provisioning initiated for ${wfa.dataPill(params.flowVariables.requestedBy, 'string')}. Change Request: ${wfa.dataPill(changeRequest.record, 'reference')}`,
                }),
            }
        )

        // Step 6: forEach loop - Process asset list with pill references
        wfa.flowLogic.forEach(
            wfa.dataPill(params.flowVariables.assetList, 'array.object'),
            { $id: Now.ID['foreach_assets'], annotation: 'Process each asset item' },
            (asset) => {
                // Create a task for each asset item
                const assetTask = wfa.action(
                    action.core.createTask,
                    { $id: Now.ID['create_asset_task'], annotation: 'Create asset provisioning task' },
                    {
                        task_table: 'sc_task',
                        field_values: TemplateValue({
                            short_description: `Deploy ${wfa.dataPill(asset.assetName, 'string')} for ${wfa.dataPill(params.flowVariables.requestedBy, 'string')}`,
                            description: `Asset: ${wfa.dataPill(asset.assetName, 'string')}, Critical: ${wfa.dataPill(asset.isCritical, 'boolean')}, Business Unit: ${wfa.dataPill(params.flowVariables.businessUnit, 'string')}`,
                            state: 1,
                        }),
                        wait: false,
                    }
                )

                // Log each asset task with pill references
                wfa.action(
                    action.core.log,
                    { $id: Now.ID['log_asset_task'], annotation: 'Log asset task creation' },
                    {
                        log_level: 'info',
                        log_message: `Created task for asset: ${wfa.dataPill(asset.assetName, 'string')} (Critical: ${wfa.dataPill(asset.isCritical, 'boolean')}) - Task: ${wfa.dataPill(assetTask.Record, 'reference')}`,
                    }
                )

                // Conditional logic based on asset criticality
                wfa.flowLogic.if(
                    {
                        $id: Now.ID['if_asset_critical'],
                        condition: `${wfa.dataPill(asset.isCritical, 'boolean')}==true`,
                        annotation: 'Check if asset is critical',
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            { $id: Now.ID['log_critical_asset'], annotation: 'Log critical asset' },
                            {
                                log_level: 'warn',
                                log_message: `CRITICAL ASSET: ${wfa.dataPill(asset.assetName, 'string')} requires immediate attention for ${wfa.dataPill(params.flowVariables.requestedBy, 'string')} in ${wfa.dataPill(params.flowVariables.businessUnit, 'string')}`,
                            }
                        )
                    }
                )
            }
        )

        // Step 7: forEach loop - Process software packages with pill references
        wfa.flowLogic.forEach(
            wfa.dataPill(params.flowVariables.softwarePackages, 'array.object'),
            { $id: Now.ID['foreach_software'], annotation: 'Process each software package' },
            (software) => {
                // Create a software installation task for each package
                wfa.action(
                    action.core.createTask,
                    { $id: Now.ID['create_software_task'], annotation: 'Create software installation task' },
                    {
                        task_table: 'sc_task',
                        field_values: TemplateValue({
                            short_description: `Install ${wfa.dataPill(software.packageName, 'string')} for ${wfa.dataPill(params.flowVariables.requestedBy, 'string')}`,
                            description: `Package: ${wfa.dataPill(software.packageName, 'string')}, Version: ${wfa.dataPill(software.version, 'string')}, Unit: ${wfa.dataPill(params.flowVariables.businessUnit, 'string')}`,
                            state: 1,
                        }),
                        wait: false,
                    }
                )

                // Log software installation with nested pill references
                wfa.action(
                    action.core.log,
                    { $id: Now.ID['log_software_installation'], annotation: 'Log software installation' },
                    {
                        log_level: 'info',
                        log_message: `Scheduled software installation: ${wfa.dataPill(software.packageName, 'string')} v${wfa.dataPill(software.version, 'string')} for ${wfa.dataPill(params.flowVariables.requestedBy, 'string')} in ${wfa.dataPill(params.flowVariables.businessUnit, 'string')}`,
                    }
                )
            }
        )

        // Step 8: Look up the caller to get their email address
        const callerUser = wfa.action(
            action.core.lookUpRecord,
            { $id: Now.ID['lookup_caller_user'], annotation: 'Look up caller user for email address' },
            {
                table: 'sys_user',
                conditions: `user_name=${wfa.dataPill(params.flowVariables.requestedBy, 'string')}`,
            }
        )

        // Step 9: Send notification email with complex pill references using proper email address
        wfa.action(
            action.core.sendEmail,
            { $id: Now.ID['send_provisioning_email'], annotation: 'Send provisioning notification email' },
            {
                ah_to: `${wfa.dataPill(callerUser.Record.email, 'string')}`,
                ah_subject: `IT Asset Provisioning for ${wfa.dataPill(params.flowVariables.businessUnit, 'string')} - In Progress`,
                ah_body: `<html><body>
                    <h2>IT Asset Provisioning Update</h2>
                    <p>Your IT asset provisioning request has been initiated. Your assets and software will be deployed shortly.</p>
                </body></html>`,
                watermark_email: false,
            }
        )

        // Step 10: Final log with comprehensive pill references
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_provisioning_complete'], annotation: 'Log provisioning completion' },
            {
                log_level: 'info',
                log_message: `IT asset provisioning workflow completed for ${wfa.dataPill(params.flowVariables.requestedBy, 'string')}. Incident: ${wfa.dataPill(assetIncident.record, 'reference')}, Change Request: ${wfa.dataPill(changeRequest.record, 'reference')}, Trigger Table: ${wfa.dataPill(params.trigger.table_name, 'string')}`,
            }
        )
    }
)
